function run(){const s=Application('Safari'),w=s.windows[0];if(w.id()!==1296||!w.currentTab.url().startsWith('http://127.0.0.1:4185/#document='))throw Error('Not owned VDoc window');const p=Application('System Events').processes.byName('Safari'),a=p.windows[0];function read(e,depth){const v={};for(const [key,fn] of [['role',()=>e.role()],['name',()=>e.name()],['description',()=>e.description()],['value',()=>e.value()]])try{v[key]=fn()}catch{}if(depth>0)try{v.children=e.uiElements().slice(0,50).map(c=>read(c,depth-1))}catch{}return v}return JSON.stringify({windowId:w.id(),url:w.currentTab.url(),frontmost:p.frontmost(),tree:read(a,4)})}
